import{_ as a}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as o,o as d,X as t}from"./chunks/vendor-vueuse.XPft87tp.js";const h=JSON.parse('{"title":"数据库三大范式","description":"","frontmatter":{},"headers":[],"relativePath":"mysql/database-normalization.md","filePath":"mysql/database-normalization.md","lastUpdated":1786990830000}'),r={name:"mysql/database-normalization.md"};function i(c,e,n,l,s,_){return d(),o("div",null,e[0]||(e[0]=[t('<h1 id="数据库三大范式" tabindex="-1">数据库三大范式 <a class="header-anchor" href="#数据库三大范式" aria-label="Permalink to &quot;数据库三大范式&quot;">​</a></h1><h3 id="_1nf-字段必须是原子的" tabindex="-1">1NF：字段必须是原子的 <a class="header-anchor" href="#_1nf-字段必须是原子的" aria-label="Permalink to &quot;1NF：字段必须是原子的&quot;">​</a></h3><p>第一范式要求列不能再拆。把「北京,朝阳」塞进一个 <code>address</code>，按区筛选、按区统计都会变成字符串解析，索引也帮不上忙。省、市、区、详细地址拆开后，每一列都是独立的过滤条件。</p><p>原子性是相对业务的。身份证号通常整列保存，不必拆成地区码和序号；一旦业务真的要按地区码检索，再拆才有意义。</p><h3 id="_2nf-非主键列必须依赖整个主键" tabindex="-1">2NF：非主键列必须依赖整个主键 <a class="header-anchor" href="#_2nf-非主键列必须依赖整个主键" aria-label="Permalink to &quot;2NF：非主键列必须依赖整个主键&quot;">​</a></h3><p>第二范式建立在 1NF 之上：非主键列要完全依赖主键，不能只依赖复合主键的一部分。</p><p>订单明细如果以 <code>(order_id, sku_id)</code> 做主键，<code>user_name</code>、<code>order_time</code> 只由 <code>order_id</code> 决定，和买了哪件 SKU 无关。这些列放在明细表里会出现：</p><ul><li>同一订单多行重复用户名，浪费空间</li><li>改用户名要改多行，漏改就会不一致</li></ul><p>正确做法是用户名、下单时间留在订单表，明细表只保留真正依赖 <code>(order_id, sku_id)</code> 的字段，例如 <code>quantity</code>、<code>sku_price</code>。</p><p>单列主键的表天然满足 2NF，部分依赖主要出现在复合主键上。</p><h3 id="_3nf-去掉传递依赖" tabindex="-1">3NF：去掉传递依赖 <a class="header-anchor" href="#_3nf-去掉传递依赖" aria-label="Permalink to &quot;3NF：去掉传递依赖&quot;">​</a></h3><p>第三范式要求非主键列之间不能互相决定。员工表里同时存 <code>dept_id</code> 和 <code>dept_name</code>，部门名由部门 ID 决定，不由员工 ID 决定。部门改名时，所有员工行都要跟着改，这就是传递依赖带来的更新异常。</p><p>部门名放到部门表，员工表只留 <code>dept_id</code>。需要展示时再 JOIN，或在读多写少的列表页做有控制的冗余。</p><h3 id="何时反范式" tabindex="-1">何时反范式 <a class="header-anchor" href="#何时反范式" aria-label="Permalink to &quot;何时反范式&quot;">​</a></h3><p>范式减少冗余和更新异常，代价是查询要 JOIN。列表页每次都联三张表拿用户名、商品名，延迟和复杂度都会上去。</p><p>常见折中是把「几乎不改、读极热」的字段冗余过来，例如订单表存下单时的 <code>user_name</code>、<code>sku_name</code> 快照。这是用空间和一点一致性成本换查询，需要在写入路径同步更新，而不是随手复制一列就算完。</p>',16)]))}const u=a(r,[["render",i]]);export{h as __pageData,u as default};
